
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbeb0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbeb0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.298828398058361e+00, -3.236516216839869e+00, -3.149249329734508e+00, -3.028464116274401e+00, -2.864095752156621e+00, -2.645801970425445e+00, -2.365843347781335e+00, -2.024228600427114e+00, -1.635232889941573e+00, -1.228224298073839e+00, -8.306726538892446e-01, -5.737843018617623e-01, -4.998256085750605e-01, -4.114992406814263e-01, -2.974427499971120e-01, -1.875274568222533e-01, -1.003587727166239e-01, -3.714419692089507e-02, -8.108948816827928e-03, -9.121516117303055e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


